  const cards = "<article id=\"entry-dgp-986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰκία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 986 na letra α · nº geral 986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ultraje; afronta; maus tratos. 〈αἰκής〉</p></section></article>\n<article id=\"entry-dgp-987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰκίζω,</h1><div class=\"entry-meta\"><span>DGP · ordem 987 na letra α · nº geral 987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de ἀεικίζω (só pres.; méd. mais freq.) at. e méd. maltratar; torturar; ultrajar.</p></section></article>\n<article id=\"entry-dgp-988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴκισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 988 na letra α · nº geral 988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">maus tratos; tortura; ultraje. 〈αἰκίζω〉</p></section></article>\n<article id=\"entry-dgp-989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰκῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 989 na letra α · nº geral 989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép., e ἀϊκῶς adv. indignamente; injuriosamente.</p></section></article>\n<article id=\"entry-dgp-990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴλινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 990 na letra α · nº geral 990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 queixoso; desolado; triste ♦ αἴλινον, αἴλινα adv. 2 queixosamente; lastimosamente ♦ ὁ αἴ­λινος 3 lamento fúnebre. 〈αἷ, Λίνος〉</p></section></article>\n<article id=\"entry-dgp-991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴλουρος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 991 na letra α · nº geral 991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gato; gata. 〈αἰόλος, οὐρά〉</p></section></article>\n<article id=\"entry-dgp-992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἷμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 992 na letra α · nº geral 992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sangue 2 alma; coragem; força 3 derramamento de sangue; homicídio: αἵματος δίκαι ésql. acusação de assassínio 4 menstruação 5 laços sangüíneos; parentesco: ἀφ’ αἵματος, ἐξ αἵματος, ἐν αἵματι εἷναι ser do sangue de alguém 6 líquido vermelho; suco; vinho.</p></section></article>\n<article id=\"entry-dgp-993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμακορία</h1><div class=\"entry-meta\"><span>DGP · ordem 993 na letra α · nº geral 993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e αἱμακουρία (ἡ) libação de sangue em honra dos mortos. 〈αἷμα, κορέννυμι〉</p></section></article>\n<article id=\"entry-dgp-994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμακτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 994 na letra α · nº geral 994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ensangüentado. 〈αἱμάσσω〉</p></section></article>\n<article id=\"entry-dgp-995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 995 na letra α · nº geral 995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">onda de sangue. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμασιά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 996 na letra α · nº geral 996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espinho; sebe de espinho; sebe 2 muro feito de pedras (sobrepostas, sem argamassa). 〈αἱμός〉</p></section></article>\n<article id=\"entry-dgp-997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 997 na letra α · nº geral 997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. αἱμάξω, aor. ᾕμαξα, perf. desus.) 1 cobrir de sangue; ferir; matar 2 intr. estar ou ficar ensangüentado; cobrir-se de sangue ♦ méd. 3 manchar de sangue. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματεκχυσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 998 na letra α · nº geral 998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. derramamento de sangue. 〈αἷμα, ἐκχέω〉</p></section></article>\n<article id=\"entry-dgp-999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματηρός, ά</h1><div class=\"entry-meta\"><span>DGP · ordem 999 na letra α · nº geral 999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ός, όν 1 que causa derramamento de sangue; ávido de sangue; assassino 2 ensangüentado 3 de sangue. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-1000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματηφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1000 na letra α · nº geral 1000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que causa derramamento de sangue; sangrento. 〈αἷμα, φέρω〉</p></section></article>\n<article id=\"entry-dgp-1001\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1001 na letra α · nº geral 1001</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ensangüentar 2 (inseto) chupar sangue. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-1002\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1002 na letra α · nº geral 1002</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de sangue; sangrento; ensangüentado 2 da cor do sangue; purpúreo. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-1003\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματολοιχός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1003 na letra α · nº geral 1003</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que lambe sangue. 〈αἷμα, λείχω〉</p></section></article>\n<article id=\"entry-dgp-1004\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματορρόφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1004 na letra α · nº geral 1004</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que engole sangue. 〈αἷμα, ῥοφέω〉</p></section></article>\n<article id=\"entry-dgp-1005\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματόρρυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1005 na letra α · nº geral 1005</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que verte sangue; que faz escorrer sangue. 〈αἷμα, ῥέω〉</p></section></article>\n<article id=\"entry-dgp-1006\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματοσταγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1006 na letra α · nº geral 1006</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gotejante de sangue. 〈αἷμα, στάζω〉</p></section></article>\n<article id=\"entry-dgp-1007\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1007 na letra α · nº geral 1007</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ensangüentar 2 converter em sangue ♦ pas. 3 estar ensangüentado; cobrir-se de sangue. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-1008\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1008 na letra α · nº geral 1008</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sangrento; sanguinolento 2 da natureza do sangue. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-1009\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμοβαρής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1009 na letra α · nº geral 1009</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de sangue. 〈αἷμα, βάρος〉</p></section></article>\n<article id=\"entry-dgp-1010\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμόδιψος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1010 na letra α · nº geral 1010</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sedento de sangue. 〈αἷμα, δίψα〉</p></section></article>\n<article id=\"entry-dgp-1011\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἱμονίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1011 na letra α · nº geral 1011</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">descendente de Hêmon. 〈Αἵμων〉</p></section></article>\n<article id=\"entry-dgp-1012\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμορραγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1012 na letra α · nº geral 1012</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que perde sangue; que sofre hemorragia. 〈αἷμα, ῥήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-1013\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμόρραντος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1013 na letra α · nº geral 1013</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">orvalhado de sangue; ensopado de sangue. 〈αἷμα, ῥαίνω〉</p></section></article>\n<article id=\"entry-dgp-1014\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμορροέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1014 na letra α · nº geral 1014</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perder sangue; ter hemorragia. 〈αἱμόρροος〉</p></section></article>\n<article id=\"entry-dgp-1015\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμόρροος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 1015 na letra α · nº geral 1015</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que sofre hemorragia (veia) 2 que causa hemorragia. 〈αἷμα, ῥεω〉</p></section></article>\n<article id=\"entry-dgp-1016\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμοσφαγεῖος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1016 na letra α · nº geral 1016</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que faz correr sangue. 〈αἷμα, σφάττω〉</p></section></article>\n<article id=\"entry-dgp-1017\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμυλία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1017 na letra α · nº geral 1017</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">graça; encanto; lisonja. 〈αἱμύλος〉</p></section></article>\n<article id=\"entry-dgp-1018\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμύλιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1018 na letra α · nº geral 1018</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = αἱμύλος.</p></section></article>\n<article id=\"entry-dgp-1019\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμύλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1019 na letra α · nº geral 1019</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) lisonjear; enganar. 〈αἱμύλος〉</p></section></article>\n<article id=\"entry-dgp-1020\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμύλος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 1020 na letra α · nº geral 1020</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον poét. 1 ladino; astuto; hábil 2 lisonjeiro; enganador; sedutor (pessoa).</p></section></article>\n<article id=\"entry-dgp-1021\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1021 na letra α · nº geral 1021</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que é vermelho como sangue. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-1022\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἵμων1, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1022 na letra α · nº geral 1022</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος duv. apaixonado por ou hábil em, gen.</p></section></article>\n<article id=\"entry-dgp-1023\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἵμων2, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1023 na letra α · nº geral 1023</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 sangrento; cruento ♦ ὁ Αἵμων 2 Hêmon, filho de Creonte, rei de Tebas. 〈αἷμα〉</p></section></article>\n<article id=\"entry-dgp-1024\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνά</h1><div class=\"entry-meta\"><span>DGP · ordem 1024 na letra α · nº geral 1024</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. αἰνός.</p></section></article>\n<article id=\"entry-dgp-1025\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰναρέτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1025 na letra α · nº geral 1025</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. αἰναρέτη (masc.) terrivelmente corajoso. 〈αἰνός, ἀρετή〉</p></section></article>\n<article id=\"entry-dgp-1026\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰνέας</h1><div class=\"entry-meta\"><span>DGP · ordem 1026 na letra α · nº geral 1026</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór., e át. Αἰνείας, ου (ὁ) Enéias, herói troiano, filho de Anquises e de Afrodite.</p></section></article>\n<article id=\"entry-dgp-1027\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴνεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1027 na letra α · nº geral 1027</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. louvor. 〈αἰνέω〉</p></section></article>\n<article id=\"entry-dgp-1028\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνετός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1028 na letra α · nº geral 1028</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">louvável. 〈αἰνέω〉</p></section></article>\n<article id=\"entry-dgp-1029\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1029 na letra α · nº geral 1029</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ᾔνουν, fut. αἰνέσω, aor. ᾔνεσα, perf. desus.; pas. aor. ᾐνέθην, perf. desus.) 1 louvar; elogiar; celebrar 2 aprovar 3 agradecer 4 aquiescer em; permitir, com ac. e part.: ἰόντ’ αἰνέσατ’ ἐκ δόμων ésql. deixai-o sair da (vossa) casa 5 contentar-se; resignar-se 6 prometer algo, ac., a alguém, dat. 7 aconselhar; recomendar, inf. 〈αἶνος〉</p></section></article>\n<article id=\"entry-dgp-1030\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1030 na letra α · nº geral 1030</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">louvor; glória. 〈αἶνος〉</p></section></article>\n<article id=\"entry-dgp-1031\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1031 na letra α · nº geral 1031</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ênia, cidade da Etólia.</p></section></article>\n<article id=\"entry-dgp-1032\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰνιάν, ᾶνος</h1><div class=\"entry-meta\"><span>DGP · ordem 1032 na letra α · nº geral 1032</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem., n.) de Ênia; eniano. 〈Αἰνία〉</p></section></article>\n<article id=\"entry-dgp-1033\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴνιγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1033 na letra α · nº geral 1033</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enigma; expressão enigmática; palavra obscura; ἐν αἰνίγματι de maneira confusa 2 alusão; insinuação. 〈αἰνίσσομαι〉</p></section></article>\n<article id=\"entry-dgp-1034\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνιγματώδης, ης, εν</h1><div class=\"entry-meta\"><span>DGP · ordem 1034 na letra α · nº geral 1034</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">enigmático. 〈αἴνιγμα〉</p></section></article>\n<article id=\"entry-dgp-1035\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνιγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1035 na letra α · nº geral 1035</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">enigma; δι᾽ αἰνιγμῶν, ἐν αἰνιγμοῖσι por enigmas.</p></section></article>\n<article id=\"entry-dgp-1036\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1036 na letra α · nº geral 1036</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) = αἰνέω.</p></section></article>\n<article id=\"entry-dgp-1037\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνικτηρίως</h1><div class=\"entry-meta\"><span>DGP · ordem 1037 na letra α · nº geral 1037</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. por enigmas.</p></section></article>\n<article id=\"entry-dgp-1038\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνικτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1038 na letra α · nº geral 1038</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">expresso por enigmas, por palavras veladas. 〈αἰνίσσομαι〉</p></section></article>\n<article id=\"entry-dgp-1039\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἴνιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1039 na letra α · nº geral 1039</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Ênio, n. de homem ♦ adj. 2 de Enos, cidade da Trácia.</p></section></article>\n<article id=\"entry-dgp-1040\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνίσσομαι,</h1><div class=\"entry-meta\"><span>DGP · ordem 1040 na letra α · nº geral 1040</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ίττομαι (fut. αἰνίξομαι, aor. ᾐνιξάμην; pas. aor. ᾐνίχθην, perf. ᾔνιγμαι) 1 falar por enigmas; falar obscuramente; fazer uma alusão obscura 2 expressar por enigmas; insinuar. 〈αἶνος〉</p></section></article>\n<article id=\"entry-dgp-1041\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1041 na letra α · nº geral 1041</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em αἰνόθεν αἰνῶς hom. de mal a pior. 〈αἰνός〉</p></section></article>\n<article id=\"entry-dgp-1042\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰνόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1042 na letra α · nº geral 1042</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv de Enos, na Trácia. 〈Αἶνος〉</p></section></article>\n<article id=\"entry-dgp-1043\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνολαμπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1043 na letra α · nº geral 1043</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem um brilho terrível. 〈αἰνός, λάμπω〉</p></section></article>\n<article id=\"entry-dgp-1044\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνόλεκτρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1044 na letra α · nº geral 1044</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cujo leito é funesto. 〈αἰνός, λέκτρον〉</p></section></article>\n<article id=\"entry-dgp-1045\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνόμορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1045 na letra α · nº geral 1045</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de funesto destino. 〈αἰνός, μόρος〉</p></section></article>\n<article id=\"entry-dgp-1046\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνοπαθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1046 na letra α · nº geral 1046</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que sofre terrivelmente. 〈αἰνός, παθεῖν〉</p></section></article>\n<article id=\"entry-dgp-1047\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰνόπαρις, ιδος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1047 na letra α · nº geral 1047</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o funesto Páris. 〈αἰνός, Πάρις〉</p></section></article>\n<article id=\"entry-dgp-1048\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνοπάτηρ</h1><div class=\"entry-meta\"><span>DGP · ordem 1048 na letra α · nº geral 1048</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só voc. αἰνόπατερ pai infeliz. 〈αἰνός, πατήρ〉</p></section></article>\n<article id=\"entry-dgp-1049\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1049 na letra α · nº geral 1049</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 terrível; medonho; formidável ♦ αἰνά adv. 2 terrivelmente.</p></section></article>\n<article id=\"entry-dgp-1050\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἶνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1050 na letra α · nº geral 1050</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 elogio; louvor 2 conto 3 apólogo; sentença; provérbio.</p></section></article>\n<article id=\"entry-dgp-1051\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἶνος, ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 1051 na letra α · nº geral 1051</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 masc. Eno, n. de homem 2 fem. Eno, cidade da Trácia.</p></section></article>\n<article id=\"entry-dgp-1052\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴνυμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1052 na letra α · nº geral 1052</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) pegar; agarrar, apoderar-se de, ac. ou gen. partit.</p></section></article>\n<article id=\"entry-dgp-1053\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1053 na letra α · nº geral 1053</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. terrivelmente; grandemente.</p></section></article>\n<article id=\"entry-dgp-1054\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴξ, αἰγός (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1054 na letra α · nº geral 1054</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cabra; bode 2 cabra selvagem; cabrito montês 3 espécie de ave aquática 4 Cabra, a estrela Capela 5 meteoro inflamado 6 pl. ondas.</p></section></article>\n<article id=\"entry-dgp-1055\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀΐξασθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1055 na letra α · nº geral 1055</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. méd. de ἀΐσσω.</p></section></article>\n<article id=\"entry-dgp-1056\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀΐξω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1056 na letra α · nº geral 1056</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de ἀΐσσω.</p></section></article>\n<article id=\"entry-dgp-1057\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰολεῖς, έων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1057 na letra α · nº geral 1057</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os eólios, uma das quatro principais tribos helênicas.</p></section></article>\n<article id=\"entry-dgp-1058\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰολίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1058 na letra α · nº geral 1058</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Eólide, filho ou descendente de Éolo. 〈Αἴολος〉</p></section></article>\n<article id=\"entry-dgp-1059\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰολίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1059 na letra α · nº geral 1059</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falar em dialeto eólico 2 cantar ou compor à maneira eólica. 〈Αἰολεῖς〉</p></section></article>\n<article id=\"entry-dgp-1060\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰολικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1060 na letra α · nº geral 1060</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eólico; da Eólia. 〈Αἰολεῖς〉</p></section></article>\n<article id=\"entry-dgp-1061\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰόλιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1061 na letra α · nº geral 1061</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eólio. 〈Αἰολεῖς〉</p></section></article>\n<article id=\"entry-dgp-1062\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰολίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1062 na letra α · nº geral 1062</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 eólio ♦ ἡ Αἰολίς [χώρα] 2 Eó­lia, região da Ásia Menor. 〈Αἰολεῖς〉</p></section></article>\n<article id=\"entry-dgp-1063\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰόλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1063 na letra α · nº geral 1063</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 agitar vivamente; fazer girar 2 ornar com diversas cores; matizar.</p></section></article>\n<article id=\"entry-dgp-1064\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰολοθώρηξ, ηκος</h1><div class=\"entry-meta\"><span>DGP · ordem 1064 na letra α · nº geral 1064</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) jôn. de couraça pintada de várias cores ou de couraça brilhante. 〈αἰόλος, θώραξ〉</p></section></article>\n<article id=\"entry-dgp-1065\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰολοκένταυρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1065 na letra α · nº geral 1065</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Centauro ágil, ser fictício.</p></section></article>\n<article id=\"entry-dgp-1066\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰολόμητις, ιος</h1><div class=\"entry-meta\"><span>DGP · ordem 1066 na letra α · nº geral 1066</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) fértil em astúcias. 〈αἰόλος, μῆτις〉</p></section></article>\n<article id=\"entry-dgp-1067\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰολομίτρης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1067 na letra α · nº geral 1067</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que tem cinturão de várias cores 2 que tem turbante de várias cores. 〈αἰόλος, μίτρα〉</p></section></article>\n<article id=\"entry-dgp-1068\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰολόπωλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1068 na letra α · nº geral 1068</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem corcéis ágeis. 〈αἰόλος, πῶλος〉</p></section></article>\n<article id=\"entry-dgp-1069\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰόλος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 1069 na letra α · nº geral 1069</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 que se agita vivamente; móbil; ágil 2 cambiante; variado 3 de aspecto variável; de cores cam- biantes; matizado ♦ ὁ Αἴολος 4 Éolo, deus dos ventos.</p></section></article>\n<article id=\"entry-dgp-1070\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰολόστομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1070 na letra α · nº geral 1070</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de linguagem ambígua. 〈αἰόλος, στόμα〉</p></section></article>\n<article id=\"entry-dgp-1071\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄϊον</h1><div class=\"entry-meta\"><span>DGP · ordem 1071 na letra α · nº geral 1071</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἀΐω1 e ἀΐω2.</p></section></article>\n<article id=\"entry-dgp-1072\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπεινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1072 na letra α · nº geral 1072</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alto; escarpado; difícil de atingir 2 difícil de compreender; profundo. 〈αἷπος〉</p></section></article>\n<article id=\"entry-dgp-1073\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἵπερ</h1><div class=\"entry-meta\"><span>DGP · ordem 1073 na letra α · nº geral 1073</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eól. = εἴπερ.</p></section></article>\n<article id=\"entry-dgp-1074\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἵπερ</h1><div class=\"entry-meta\"><span>DGP · ordem 1074 na letra α · nº geral 1074</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. pl. fem. de ὅσπερ.</p></section></article>\n<article id=\"entry-dgp-1075\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1075 na letra α · nº geral 1075</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 circundado de escarpas 2 impetuoso; violento (furacão). 〈αἷπος〉</p></section></article>\n<article id=\"entry-dgp-1076\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1076 na letra α · nº geral 1076</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) 1 guardar ou guiar cabras ♦ pas. 2 pastar. 〈αἰπόλος〉</p></section></article>\n<article id=\"entry-dgp-1077\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπόλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1077 na letra α · nº geral 1077</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rebanho de cabras; rebanho 2 pastagem de cabras. 〈αἰπόλος〉</p></section></article>\n<article id=\"entry-dgp-1078\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπόλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1078 na letra α · nº geral 1078</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cabreiro. 〈αἴξ, πολέω〉</p></section></article>\n<article id=\"entry-dgp-1079\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἷπος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1079 na letra α · nº geral 1079</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 altura; elevação 2 meta difícil de atingir. 〈αἰπύς〉</p></section></article>\n<article id=\"entry-dgp-1080\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1080 na letra α · nº geral 1080</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">αἰπύς.</p></section></article>\n<article id=\"entry-dgp-1081\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπυμήτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1081 na letra α · nº geral 1081</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. αἰπυμῆτα (masc.) que tem pensamentos elevados. 〈αἰπύς, μῆτις〉</p></section></article>\n<article id=\"entry-dgp-1082\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπύνωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1082 na letra α · nº geral 1082</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">situado no cume da montanha. 〈αἰπύς, νῶτον〉</p></section></article>\n<article id=\"entry-dgp-1083\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰπύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>DGP · ordem 1083 na letra α · nº geral 1083</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. 1 alto e escarpado; alto e abrupto; elevado 2 difícil de atingir; árduo: αἰπύ οἱ ἐσσεῖται hom. ser-lhe-á difícil 3 pendurado do alto: ἁψαμένη βρόχον αἰπύν hom. suspensa de laço mortal 4 próprio para precipitar-se 5 profundo 6 que se eleva muito alto; retumbante ♦ τὸ Αἰπύ 7 Epi, “a Escarpada”, cidade do país de Nestor.</p></section></article>\n<article id=\"entry-dgp-1084\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰπύτιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1084 na letra α · nº geral 1084</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Épito. 〈Αἴπυτος〉</p></section></article>\n<article id=\"entry-dgp-1085\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἴπυτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1085 na letra α · nº geral 1085</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Épito, rei da Arcádia.</p></section></article>\n";
